self.PH_PROVINCES = self.PH_PLACES.flatMap(r => r.provinces.map(p => p.name));
(function () {
  const provs = self.PH_PLACES.flatMap(r => r.provinces);
  const norm = s => String(s || '').toLowerCase().replace(/\bcity of\b|\bcity\b/g, '').replace(/[^a-z0-9ñ]+/g, ' ').trim();
  const byName = n => provs.find(p => p.name === n);
  self.phCities = prov => (byName(prov) || { cities: [] }).cities;
  self.phCityPoint = (prov, city) => { const c = self.phCities(prov).find(x => norm(x.n) === norm(city)); return c && c.y ? [c.y, c.x] : null; };
  self.phCityCode = (prov, city) => { const c = self.phCities(prov).find(x => norm(x.n) === norm(city)); return c ? c.c : ''; };
  // Province for an old listing that only has a city name. Cebu first: some names exist in more than one province.
  self.phProvinceOf = function (area) {
    const a = norm(area); if (!a) return '';
    const order = provs.slice().sort((x, y) => (y.name === 'Cebu') - (x.name === 'Cebu'));
    for (const p of order) if (norm(p.name) === a || p.cities.some(c => norm(c.n) === a)) return p.name;
    return '';
  };
  const cache = {};
  self.phBarangays = function (prov, cityCode) {
    const p = byName(prov); if (!p || !cityCode) return Promise.resolve([]);
    cache[p.slug] = cache[p.slug] || fetch('brgy/' + p.slug + '.json').then(r => r.ok ? r.json() : {}).catch(() => { delete cache[p.slug]; return {}; });
    return cache[p.slug].then(d => d[cityCode] || []);
  };
})();
